import React from 'react';
import { Box, Grid, Paper, Typography } from '@mui/material';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell,
  Event as EventIcon,
  EventNote as EventNoteIcon,
  PendingActions as PendingActionsIcon,
  EventAvailable as EventAvailableIcon,
  CheckCircle as CheckCircleIcon
} from 'recharts';
import { format } from 'date-fns';

const COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#8884d8'];

const SummaryCard = ({ title, value, icon: Icon, color }) => (
  <Paper 
    elevation={2} 
    sx={{ 
      p: 3, 
      borderRadius: 2,
      height: '100%',
      borderLeft: `4px solid ${color}`
    }}
  >
    <Box display="flex" justifyContent="space-between" alignItems="center">
      <Box>
        <Typography variant="subtitle2" color="textSecondary">
          {title}
        </Typography>
        <Typography variant="h4" fontWeight="bold">
          {value}
        </Typography>
      </Box>
      <Box 
        sx={{ 
          backgroundColor: `${color}20`, 
          p: 1.5,
          borderRadius: '50%',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center'
        }}
      >
        <Icon sx={{ color }} />
      </Box>
    </Box>
  </Paper>
);

const AppointmentTrends = ({ data }) => {
  // Process data to get weekly trends
  const processTrendData = (appointments) => {
    const today = new Date();
    const lastWeek = new Date(today);
    lastWeek.setDate(today.getDate() - 7);

    return Array.from({ length: 7 }, (_, i) => {
      const date = new Date(lastWeek);
      date.setDate(lastWeek.getDate() + i);
      const dateStr = format(date, 'MMM dd');
      const count = appointments.filter(apt => {
        const aptDate = new Date(apt.appointmentDate);
        return aptDate.toDateString() === date.toDateString();
      }).length;

      return { date: dateStr, appointments: count };
    });
  };

  return (
    <Paper elevation={2} sx={{ p: 3, borderRadius: 2, height: '100%' }}>
      <Typography variant="h6" gutterBottom>Appointment Trends</Typography>
      <Box sx={{ height: 300, mt: 2 }}>
        <ResponsiveContainer width="100%" height="100%">
          <BarChart data={processTrendData(data)}>
            <CartesianGrid strokeDasharray="3 3" />
            <XAxis dataKey="date" />
            <YAxis />
            <Tooltip />
            <Legend />
            <Bar dataKey="appointments" fill="#8884d8" name="Appointments" />
          </BarChart>
        </ResponsiveContainer>
      </Box>
    </Paper>
  );
};

const StatusDistribution = ({ data }) => {
  const statusData = [
    { name: 'Pending', value: data.filter(a => a.status === 'PENDING').length },
    { name: 'Confirmed', value: data.filter(a => a.status === 'CONFIRMED').length },
    { name: 'Completed', value: data.filter(a => a.status === 'COMPLETED').length },
    { name: 'Cancelled', value: data.filter(a => a.status === 'CANCELLED').length },
  ];

  return (
    <Paper elevation={2} sx={{ p: 3, borderRadius: 2, height: '100%' }}>
      <Typography variant="h6" gutterBottom>Appointment Status</Typography>
      <Box sx={{ height: 300, mt: 2 }}>
        <ResponsiveContainer width="100%" height="100%">
          <PieChart>
            <Pie
              data={statusData}
              cx="50%"
              cy="50%"
              labelLine={false}
              outerRadius={80}
              fill="#8884d8"
              dataKey="value"
              label={({ name, percent }) => 
                `${name}: ${(percent * 100).toFixed(0)}%`
              }
            >
              {statusData.map((entry, index) => (
                <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
              ))}
            </Pie>
            <Tooltip formatter={(value) => [`${value} appointments`, 'Count']} />
            <Legend />
          </PieChart>
        </ResponsiveContainer>
      </Box>
    </Paper>
  );
};

const DashboardMetrics = ({ appointments, loading }) => {
  if (loading) return <div>Loading metrics...</div>;

  const stats = {
    total: appointments.length,
    pending: appointments.filter(a => a.status === 'PENDING').length,
    confirmed: appointments.filter(a => a.status === 'CONFIRMED').length,
    completed: appointments.filter(a => a.status === 'COMPLETED').length,
  };

  return (
    <Box sx={{ mb: 4 }}>
      <Grid container spacing={3} sx={{ mb: 3 }}>
        <Grid item xs={12} sm={6} md={3}>
          <SummaryCard 
            title="Total Appointments" 
            value={stats.total} 
            icon={() => <EventNoteIcon />} 
            color="#4e73df"
          />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <SummaryCard 
            title="Pending" 
            value={stats.pending} 
            icon={() => <PendingActionsIcon />} 
            color="#f6c23e"
          />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <SummaryCard 
            title="Confirmed" 
            value={stats.confirmed} 
            icon={() => <EventAvailableIcon />} 
            color="#1cc88a"
          />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <SummaryCard 
            title="Completed" 
            value={stats.completed} 
            icon={() => <CheckCircleIcon />} 
            color="#36b9cc"
          />
        </Grid>
      </Grid>

      <Grid container spacing={3}>
        <Grid item xs={12} md={8}>
          <AppointmentTrends data={appointments} />
        </Grid>
        <Grid item xs={12} md={4}>
          <StatusDistribution data={appointments} />
        </Grid>
      </Grid>
    </Box>
  );
};

export default DashboardMetrics;
